Lemma PD5 : decode_any PW5 = Some (Store SZ4 15 14 0, 4%Z). Proof. vm_refl. Qed.
Lemma PD6 : decode_any PW6 = Some (Op ALU_ADD 12 12 21, 4%Z). Proof. vm_refl. Qed.
