(* [comment removed for export] *)
Lemma pf_mem_rdn : forall k mem e c s i j,
  (0 <= i)%Z -> (4 * (i + Z.of_nat k) <= e)%Z -> (e < 2 ^ 64)%Z ->
  (0 <= j < Z.of_nat k)%Z ->
  rdn segs (pf_mem mem e c s i k) (Z_to_bv 64 (e - 4 * (i + Z.of_nat k) + 4 * j)) 4
